def f(a, b, m):                       # m — сколько ходов осталось
    if a + b >= 133:
        return m % 2 == 0                  # игра окончена: победил сделавший последний ход
    if m == 0:
        return False
    h = [f(a + 4, b, m - 1), f(a * 2, b, m - 1), f(a, b + 4, m - 1), f(a, b * 2, m - 1)]
    return any(h) if m % 2 != 0 else all(h)

print(*[s for s in range(1, 116) if f(17, s, 1)][:5], '…')

def g(a, b, m):                        # «ситуация возможна»: any у обоих игроков
    if a + b >= 133:
        return m % 2 == 0
    if m == 0:
        return False
    return any([g(a + 4, b, m - 1), g(a * 2, b, m - 1), g(a, b + 4, m - 1), g(a, b * 2, m - 1)])

print(min(s for s in range(1, 116) if g(17, s, 2)))

