def f(s, m):                           # «кто сделал s > 40 — проиграл»: ходы +1, +3
    if s > 40:
        return m % 2 != 0              # проиграл сделавший последний ход
    if m == 0:
        return False
    h = [f(s + 1, m - 1), f(s + 3, m - 1)]
    return any(h) if m % 2 != 0 else all(h)

print(*[s for s in range(1, 41) if not f(s, 1) and f(s, 3)])

